'use client'

// Remote-local copy of the singleton package. Kept at a different path (and
// with an extra export) from the host's copy so the two builds assign
// different module IDs to it, mirroring how two separately deployed apps
// bundle distinct copies of a shared package.
export const singleton = {
  // Unique per module evaluation: identical iff two readers share an instance.
  instanceId: Math.random().toString(36).slice(2),
  marker: 'unmodified',
}

export const remoteOnlyMarker = 'remote-copy'
